/**
 * Workstream E2 — premium trophy art manifest. One entry per catalogue trophy
 * identity (content/world.ts TROPHIES), plus the two non-trophy recognitions.
 * Files live in public/assets/career-trophies/ and are generated by
 * scripts/build-career-trophies.mjs (deterministic, no external dependencies).
 */
/** v1: 18 catalogue families (vector). v2: physically based renders for all designs + 12 event-specific designs. */
export const TROPHY_ART_VERSION = 2 as const;

export type TrophyArt = {
  id: string; name: string; designKey: string;
  /** Vector artwork (families only) used at the smallest size and as a load fallback; event designs are render-only. */
  vector: string | null;
  /** True for the 18 catalogue trophy families; false for event-specific designs. */
  family: boolean;
  /** Plain-language description used for alt text and review. */
  description: string;
  material: "SILVER" | "SILVER_GOLD" | "CRYSTAL" | "WOOD_SILVER" | "WOOD_COPPER" | "GUNMETAL" | "GOLD_SILVER" | "ENAMEL_SILVER" | "CRYSTAL_GOLD" | "RESIN_SILVER";
  silhouette: string;
};

const art = (id: string, name: string, designKey: string, material: TrophyArt["material"], silhouette: string, description: string): TrophyArt =>
  ({ id, name, designKey, vector: `${id}.svg`, family: true, material, silhouette, description });
const eventDesign = (id: string, name: string, material: TrophyArt["material"], silhouette: string, description: string): TrophyArt =>
  ({ id, name, designKey: id, vector: null, family: false, material, silhouette, description });

